141: /* Add/Remove cpu_topology interface for CPU device */
142: static int topology_add_dev(unsigned int cpu)
143: {
144: 	struct device *dev = get_cpu_device(cpu);
145: 
146: 	return sysfs_create_group(&dev->kobj, &topology_attr_group);
147: }
148: 
149: static int topology_remove_dev(unsigned int cpu)
150: {
151: 	struct device *dev = get_cpu_device(cpu);
152: 
153: 	sysfs_remove_group(&dev->kobj, &topology_attr_group);
154: 	return 0;
155: }
156: 
157: static int __init topology_sysfs_init(void)
158: {
159: 	return cpuhp_setup_state(CPUHP_TOPOLOGY_PREPARE,
160: 				 "base/topology:prepare", topology_add_dev,
161: 				 topology_remove_dev);
162: }
